(function qaLibFactory() {
  const qa = {};
  const ROLE = {
    ADMIN: 'admin', WAREHOUSE_MANAGER: 'manager', WAREHOUSE_STAFF: 'staff',
    PURCHASING: 'purchasing', SALES: 'sales', ACCOUNTANT: 'accountant'
  };
  qa.setNext = (name) => {
    if (pm.execution && typeof pm.execution.setNextRequest === 'function') {
      pm.execution.setNextRequest(name);
    } else {
      postman.setNextRequest(name);
    }
  };
  qa.get = (k) => {
    const v = pm.collectionVariables.get(k);
    if (v !== undefined && v !== null && v !== '') return v;
    return pm.environment.get(k);
  };
  qa.set = (k, v) => pm.collectionVariables.set(k, (v !== null && typeof v === 'object') ? JSON.stringify(v) : v);
  qa.unset = (k) => pm.collectionVariables.unset(k);
  qa.runId = () => String(pm.environment.get('runId') || pm.collectionVariables.get('runId') || '')
    .toLowerCase().replace(/[^a-z0-9]/g, '');
  qa.user = (company, role) => 'qa_' + qa.runId() + '_' + company.toLowerCase() + '_' + (ROLE[role] || role.toLowerCase());
  qa.email = (company, role) => qa.user(company, role) + '@qa.example.com';
  // Mật khẩu kiểm thử giả, suy ra từ runId để collection sau đăng nhập lại được (quy tắc API: 6 đến 72 ký tự).
  qa.password = () => 'QaTest-' + qa.runId() + '-Mk';
  // Ngày theo giờ Việt Nam (máy chủ chạy TZ=Asia/Ho_Chi_Minh), dạng yyyy-MM-dd.
  qa.day = (offset) => new Date(Date.now() + 7 * 3600 * 1000 + offset * 86400000).toISOString().slice(0, 10);
  qa.json = () => { try { return pm.response.json(); } catch (e) { return null; } };
  qa.data = () => { const b = qa.json(); return b ? b.data : undefined; };
  qa.content = () => {
    const d = qa.data();
    if (Array.isArray(d)) return d;
    return d && Array.isArray(d.content) ? d.content : [];
  };
  qa.brief = () => {
    let t = '';
    try { t = pm.response.text(); } catch (e) { t = ''; }
    return 'HTTP ' + pm.response.code + ': ' + t.slice(0, 500);
  };
  qa.num = (x) => (x === null || x === undefined || x === '') ? NaN : Number(x);
  qa.near = (a, b) => Math.abs(qa.num(a) - qa.num(b)) < 0.0005;
  qa.expectNum = (actual, expected, what) =>
    pm.expect(qa.near(actual, expected), what + ': nhận ' + actual + ', cần ' + expected).to.equal(true);
  qa.test = (label, fn) => pm.test(label, fn);
  qa.status = (code, label) => pm.test(label + ': HTTP ' + code, () => {
    pm.expect(pm.response.code, qa.brief()).to.eql(code);
  });
  qa.ok = (code, label) => pm.test(label + ': HTTP ' + code + ', success = true', () => {
    pm.expect(pm.response.code, qa.brief()).to.eql(code);
    const b = qa.json();
    pm.expect(b && b.success, qa.brief()).to.eql(true);
  });
  qa.error = (status, code, label) => pm.test(label + ': HTTP ' + status + ', mã ' + code, () => {
    pm.expect(pm.response.code, qa.brief()).to.eql(status);
    const b = qa.json();
    pm.expect(b && b.code, qa.brief()).to.eql(code);
  });
  qa.notFound = (label) => qa.error(404, 'NOT_FOUND', label);
  qa.forbidden = (label) => qa.error(403, 'FORBIDDEN', label);
  qa.planLimit = (limit, current, max, plan, label) =>
    pm.test(label + ': HTTP 403 PLAN_LIMIT_EXCEEDED, data = {limit: ' + limit + ', current: ' + current
      + ', max: ' + max + ', plan: ' + plan + '}', () => {
      pm.expect(pm.response.code, qa.brief()).to.eql(403);
      const b = qa.json();
      pm.expect(b && b.code, qa.brief()).to.eql('PLAN_LIMIT_EXCEEDED');
      pm.expect(b.data, 'thiếu data').to.be.an('object');
      pm.expect(b.data.limit).to.eql(limit);
      qa.expectNum(b.data.current, current, 'data.current');
      qa.expectNum(b.data.max, max, 'data.max');
      pm.expect(b.data.plan).to.eql(plan);
    });
  // Hỏi lại chính request này (tối đa pollMax lần, cách nhau pollDelayMs) cho tới khi cond() đúng.
  // Chỉ ghi kết quả test ở lần cuối, nên các lần chờ không bị tính là lỗi.
  qa.poll = (label, cond, assertFn) => {
    const key = 'poll_' + pm.info.requestName;
    const n = Number(pm.collectionVariables.get(key) || 0);
    const max = Number(pm.environment.get('pollMax') || 20);
    let ok = false;
    try { ok = !!cond(); } catch (e) { ok = false; }
    if (!ok && n < max) {
      pm.collectionVariables.set(key, n + 1);
      qa.setNext(pm.info.requestName);
      return false;
    }
    pm.collectionVariables.unset(key);
    pm.test(label, assertFn || (() => {
      pm.expect(ok, 'Hết thời gian chờ (' + (n + 1) + ' lần): ' + qa.brief()).to.equal(true);
    }));
    return ok;
  };
  qa.pollDelay = () => {
    const n = Number(pm.collectionVariables.get('poll_' + pm.info.requestName) || 0);
    if (n > 0) setTimeout(() => {}, Number(pm.environment.get('pollDelayMs') || 1500));
  };
  qa.stop = (label, msg) => {
    pm.test(label, () => pm.expect.fail(msg));
    qa.setNext(null);
  };
  qa.need = (keys) => {
    const missing = keys.filter((k) => {
      const v = qa.get(k);
      return v === undefined || v === null || v === '';
    });
    if (missing.length) {
      pm.test('Thiếu dữ liệu tiền đề (' + missing.join(', ') + '), bỏ qua request', () =>
        pm.expect.fail('Bước trước chưa tạo được: ' + missing.join(', ')));
      if (pm.execution && typeof pm.execution.skipRequest === 'function') pm.execution.skipRequest();
    }
    return missing.length === 0;
  };
  return qa;
})()
